parameters.jsCode:
// Validate the incoming webhook request from Zafar's dashboard.
// Accepts either:
//   (a) a single-patient payload: { patient_id, prediction, confidence, ... }
//   (b) a batch payload from the FL cohort file: { records: [...] }
//   (c) a health-check: { event: 'automation.health' }

const req = $input.first().json;
const body = req.body || req;

// Auth is validated at the webhook transport layer — $env is not accessible
// inside the Code node sandbox, so secret checking is skipped here.

// Health check pass-through
if (body.event === 'automation.health') {
  return [{ json: { healthCheck: true, event: body.event, data: body.data || {} } }];
}

// Single patient payload (from dashboard triggering one analysis)
if (body.patient_id) {
  const runId = 'ORC-' + new Date().toISOString().replace(/[-:.TZ]/g, '').slice(0, 14);
  return [{ json: { ...body, run_id: runId, case_index: 1, cohort_size: 1, dispatched_at: new Date().toISOString(), blind_classes: body.blind_classes || [] } }];
}

// Batch payload with records array
if (body.records && Array.isArray(body.records)) {
  const runId = 'ORC-' + new Date().toISOString().replace(/[-:.TZ]/g, '').slice(0, 14);
  return body.records.map((r, i) => ({ json: { ...r, run_id: runId, case_index: i + 1, cohort_size: body.records.length, dispatched_at: new Date().toISOString(), blind_classes: body.blind_classes || r.blind_classes || [] } }));
}

throw new Error('Invalid payload: expected patient_id, records array, or automation.health event.');

const RISK = {
  escalationThreshold: 0.45,
  recallFloor: 0.50,
  confidenceFloor: 0.70,
};

const WEIGHTS = {
  abnormal: 0.30,
  entropy: 0.30,
  urgency: 0.25,
  unreliableClass: 0.15,
};

const URGENCY_WEIGHT = {
  Low: 0.00,
  Medium: 0.50,
  High: 0.85,
  Critical: 1.00,
  Unknown: 0.50,
};

const sourceItems = $("Validate & Route Input").all().map(item => item.json || {});

function sourceForCurrentItem(currentItem, index) {
  const current = currentItem.json || {};
  const patientId = current.patient_id || current.features?.patient_id;

  if (patientId) {
    const matched = sourceItems.find(item => item.patient_id === patientId);
    if (matched) return matched;
  }

  try {
    const matchedByIndex = $("Validate & Route Input").itemMatching(index);
    if (matchedByIndex?.json) return matchedByIndex.json;
  } catch (error) {}

  return sourceItems[index] || {};
}

function firstValue(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && value !== "") {
      return value;
    }
  }
  return undefined;
}

function asNumber(value, fallback = 0) {
  const number = Number(value);
  return Number.isFinite(number) ? number : fallback;
}

function asPercentage(value) {
  const number = Number(value);

  if (!Number.isFinite(number)) {
    return "Not provided";
  }

  if (number <= 1) {
    return `${(number * 100).toFixed(1)}%`;
  }

  return `${number.toFixed(1)}%`;
}

function isNormalClass(prediction, aamiClass) {
  const predictionText = String(prediction || "").trim().toUpperCase();
  const aamiText = String(aamiClass || "").trim().toUpperCase();

  return (
    predictionText === "N" ||
    predictionText === "NORMAL" ||
    predictionText === "NORMAL SINUS RHYTHM" ||
    predictionText === "SINUS RHYTHM" ||
    aamiText === "N"
  );
}

function isAbnormalClass(prediction, aamiClass) {
  const abnormalClasses = ["S", "V", "F", "Q"];
  const predictionText = String(prediction || "").trim().toUpperCase();
  const aamiText = String(aamiClass || "").trim().toUpperCase();

  if (abnormalClasses.includes(aamiText)) return true;
  if (abnormalClasses.includes(predictionText)) return true;

  return predictionText.length > 0 && predictionText !== "N" && predictionText !== "NOT PROVIDED";
}

function buildDoctorMessage(data) {
  return [
    "CLINICAL REVIEW REQUIRED",
    "",
    `Patient: ${data.patientId}`,
    `ECG record: ${data.ecgRecord}`,
    "",
    "Clinical summary:",
    "The ECG workflow identified findings that require clinician review.",
    "",
    "Model finding:",
    `Prediction: ${data.prediction}`,
    `AAMI class: ${data.predictedClassAami}`,
    `Confidence: ${asPercentage(data.confidence)}`,
    `Uncertainty: ${data.uncertaintyLevel}`,
    `Clinical status: ${data.clinicalStatus}`,
    "",
    "Reason for review:",
    data.reviewReason,
    "",
    "Recommended action:",
    data.suggestedNextAction,
    "",
    "Technical audit:",
    `Run ID: ${data.runId}`,
    `Dominant ECG region: ${data.dominantEcgRegion}`,
    `Risk score: ${data.riskScore}`,
    `Agent/API status: ${data.apiStatus}`,
    `Pipeline note: ${data.pipelineRecommendation}`,
    "",
    "Important note:",
    "This is an AI-assisted screening output and must not be treated as a final diagnosis without clinician confirmation.",
  ].join("\n");
}

function buildPatientMessage(data) {
  if (data.clinicalStatus === "Normal" && data.reviewReason === "All governance gates passed") {
    return [
      "Hello,",
      "",
      "Your ECG recording has been processed by the clinical review system.",
      "",
      "The automated review did not identify findings that require immediate escalation. This does not replace a clinician’s judgement, and a healthcare professional may still review the result as part of normal care.",
      "",
      "Please continue to follow any advice already given by your healthcare team.",
      "",
      "If you feel unwell, have chest pain, shortness of breath, fainting, or severe symptoms, please seek urgent medical help.",
      "",
      "Thank you.",
    ].join("\n");
  }

  return [
    "Hello,",
    "",
    "Your ECG recording has been processed by the clinical review system.",
    "",
    "The automated review found features that may need checking by a healthcare professional. This does not mean a final diagnosis has been made.",
    "",
    "A clinician will review the result and confirm whether any action is needed.",
    "",
    "Please do not make medical decisions based only on this automated message.",
    "",
    "If you feel unwell, have chest pain, shortness of breath, fainting, or severe symptoms, please seek urgent medical help.",
    "",
    "Thank you.",
  ].join("\n");
}

const output = [];

for (let index = 0; index < $input.all().length; index++) {
  const api = $input.all()[index].json || {};
  const src = sourceForCurrentItem($input.all()[index], index);

  const agent = firstValue(api.agent_output, api.body?.agent_output, {});
  const features = firstValue(api.features, api.body?.features, {});

  const patientId = firstValue(
    api.patient_id,
    src.patient_id,
    features.patient_id,
    "Not provided"
  );

  const ecgRecord = firstValue(
    src.ecg_record,
    src.record_id,
    src.source_record,
    src.mit_bih_record,
    src.assigned_ecg_record,
    src.assigned_record,
    src.demo_record,
    api.ecg_record,
    api.record_id,
    api.source_record,
    api.mit_bih_record,
    api.assigned_ecg_record,
    api.assigned_record,
    api.demo_record,
    "MIT-BIH record not provided"
  );

  const runId = firstValue(src.run_id, api.run_id, "Not provided");

  const prediction = firstValue(
    features.prediction,
    src.prediction,
    src.predicted_class_aami,
    api.prediction,
    "Not provided"
  );

  const predictedClassAami = firstValue(
    src.predicted_class_aami,
    features.predicted_class_aami,
    api.predicted_class_aami,
    prediction
  );

  const confidence = asNumber(
    firstValue(features.confidence, src.confidence, api.confidence),
    0
  );

  const normalizedEntropy = asNumber(
    firstValue(src.normalized_entropy, api.normalized_entropy),
    0
  );

  const urgencyLevel = firstValue(
    agent.urgency_level,
    api.urgency_level,
    "Unknown"
  );

  const uncertaintyLevel = firstValue(
    src.uncertainty_level,
    api.uncertainty_level,
    src.risk_flag,
    "Unknown"
  );

  const classRecall = src.class_recall == null ? null : asNumber(src.class_recall, null);
  const blindClasses = Array.isArray(src.blind_classes) ? src.blind_classes : [];

  const agentStatus = firstValue(api.status, api.api_status, api.body?.status, "success");
  const apiStatus = agentStatus;

  const agentSucceeded =
    api.status === "success" ||
    api.api_status === "success" ||
    api.body?.status === "success" ||
    apiStatus === "success";

  const confidenceGap = asNumber(src.cohort_confidence_gap, 0);
  const calibratedConfidence = Math.max(0, Math.min(1, confidence + confidenceGap));

  const normalPrediction = isNormalClass(prediction, predictedClassAami);
  const abnormalPrediction = isAbnormalClass(prediction, predictedClassAami);

  const clinicalStatus = firstValue(
    api.clinical_status,
    api.body?.clinical_status,
    agent.clinical_status,
    abnormalPrediction ? "Abnormal" : "Normal"
  );

  const abnormalEvidence = clinicalStatus === "Abnormal" || abnormalPrediction;
  const classUnreliability = classRecall == null ? 0.5 : 1 - classRecall;

  const riskScore = Number((
    WEIGHTS.abnormal * (abnormalEvidence ? 1 : 0) +
    WEIGHTS.entropy * normalizedEntropy +
    WEIGHTS.urgency * (URGENCY_WEIGHT[urgencyLevel] ?? 0.5) +
    WEIGHTS.unreliableClass * classUnreliability
  ).toFixed(4));

  const reviewReasons = [];

  if (uncertaintyLevel === "High") {
    reviewReasons.push("MC-Dropout uncertainty is high");
  }

  if (abnormalEvidence) {
    if (normalPrediction) {
      reviewReasons.push(
        "Model predicted N, but supporting clinical evidence indicated abnormal rhythm features or conflicting evidence"
      );
    } else {
      reviewReasons.push(`Abnormal rhythm predicted (${prediction})`);
    }
  }

  if (calibratedConfidence < RISK.confidenceFloor) {
    reviewReasons.push(
      `Calibration-corrected confidence ${(calibratedConfidence * 100).toFixed(1)}% is below the review floor`
    );
  }

  if (urgencyLevel === "High" || urgencyLevel === "Critical") {
    reviewReasons.push(`Agent assigned ${urgencyLevel} urgency`);
  }

  if (classRecall != null && classRecall < RISK.recallFloor) {
    reviewReasons.push(`Predicted class recall ${classRecall.toFixed(3)} is below the review floor`);
  }

  if (riskScore >= RISK.escalationThreshold) {
    reviewReasons.push(`Composite risk score ${riskScore} meets the escalation threshold`);
  }

  if (!agentSucceeded) {
    reviewReasons.push(`Agent status: ${apiStatus}`);
  }

  const blindClassRisk =
    blindClasses.length > 0 &&
    uncertaintyLevel !== "Low" &&
    !blindClasses.includes(predictedClassAami);

  if (blindClassRisk) {
    reviewReasons.push(`Blind-class exposure: model cannot detect class(es) ${blindClasses.join("/")}`);
  }

  const disagreement =
    urgencyLevel === "Low" &&
    (uncertaintyLevel === "High" || calibratedConfidence < RISK.confidenceFloor);

  if (disagreement) {
    reviewReasons.push("Agent urgency was low, but pipeline uncertainty was high");
  }

  const reviewReason = reviewReasons.length
    ? reviewReasons.join(" | ")
    : "All governance gates passed";

  const suggestedNextAction = firstValue(
    agent.suggested_next_action,
    api.suggested_next_action,
    "Please review the ECG trace, model output, and dashboard report before making any clinical decision."
  );

  const pipelineRecommendation = firstValue(
    src.pipeline_recommendation,
    "Not provided"
  );

  const dominantEcgRegion = firstValue(
    src.dominant_ecg_region,
    "Not provided"
  );

  const humanReviewRequired = reviewReasons.length > 0;

  const messageData = {
    patientId,
    ecgRecord,
    runId,
    prediction,
    predictedClassAami,
    confidence,
    uncertaintyLevel,
    clinicalStatus,
    reviewReason,
    suggestedNextAction,
    dominantEcgRegion,
    riskScore,
    apiStatus,
    pipelineRecommendation,
  };

  const doctorMessage = buildDoctorMessage(messageData);

  const patientMessage = firstValue(
    agent.family_reassurance_message,
    api.family_reassurance_message,
    api.body?.family_reassurance_message,
    buildPatientMessage(messageData)
  );

  output.push({
    json: {
      run_id: runId,
      patient_id: patientId,
      ecg_record: ecgRecord,

      case_index: src.case_index,
      sample_index: src.sample_index,
      fl_checkpoint: src.fl_checkpoint,
      fl_round: src.fl_round,

      dispatched_at: src.dispatched_at,
      analysed_at: new Date().toISOString(),

      prediction,
      predicted_class_aami: predictedClassAami,
      true_class_aami: src.true_class_aami,

      correct: src.correct,
      confidence,
      calibrated_confidence: Number(calibratedConfidence.toFixed(4)),

      uncertainty_level: uncertaintyLevel,
      normalized_entropy: normalizedEntropy,
      class_recall: classRecall,

      dominant_ecg_region: dominantEcgRegion,
      qrs_shap_signed: src.qrs_shap_signed,
      p_wave_shap_signed: src.p_wave_shap_signed,
      t_wave_shap_signed: src.t_wave_shap_signed,
      ehr_triage_note: src.ehr_triage_note,

      api_status: apiStatus,
      urgency_level: urgencyLevel,

      suggested_next_action: suggestedNextAction,

      clinician_alert: doctorMessage,
      doctor_technical_alert: doctorMessage,
      family_reassurance_message: patientMessage,

      pipeline_recommendation: pipelineRecommendation,

      clinical_status: clinicalStatus,
      risk_score: riskScore,

      low_confidence_flag: calibratedConfidence < RISK.confidenceFloor,
      disagreement_flag: disagreement,
      blind_class_risk: blindClassRisk,
      ground_truth_miss: src.correct === false,

      human_review_required: humanReviewRequired,
      review_reason: reviewReason,

      governance_policy:
        `v2.0 integrated governance: abnormal=${WEIGHTS.abnormal}, entropy=${WEIGHTS.entropy}, urgency=${WEIGHTS.urgency}, class=${WEIGHTS.unreliableClass}; ` +
        `escalation=${RISK.escalationThreshold}, recall_floor=${RISK.recallFloor}, confidence_floor=${RISK.confidenceFloor}`,
    },
  });
}

return output;

// Fail-safe: agent unreachable - escalate by default.
const SRC   = $('Validate & Route Input').all().map(x => x.json);
const BY_ID = new Map(SRC.filter(s => s && s.patient_id).map(s => [s.patient_id, s]));
function resolveSrc(item, i) {
  const j = item.json || {};
  const pid = j.patient_id || (j.features && j.features.patient_id) || null;
  if (pid && BY_ID.has(pid)) return BY_ID.get(pid);
  try { const m = $('Validate & Route Input').itemMatching(i); if (m && m.json) return m.json; } catch (e) {}
  return SRC[i] || {};
}
return $input.all().map((item, _i) => {
  const src = resolveSrc(item, _i);
  const err = item.json.error || item.json.message || 'Unknown transport error';
  return { json: {
    run_id: src.run_id, patient_id: src.patient_id, case_index: src.case_index,
    sample_index: src.sample_index, fl_checkpoint: src.fl_checkpoint, fl_round: src.fl_round,
    analysed_at: new Date().toISOString(), prediction: src.prediction,
    predicted_class_aami: src.predicted_class_aami, true_class_aami: src.true_class_aami,
    correct: src.correct, confidence: src.confidence, uncertainty_level: src.uncertainty_level,
    normalized_entropy: src.normalized_entropy, class_recall: src.class_recall,
    api_status: 'transport_error', api_error_detail: String(err).slice(0, 500),
    urgency_level: 'Unknown', suggested_next_action: 'Manual clinical assessment - automated agent unavailable',
    doctor_technical_alert: 'AGENT UNAVAILABLE. No machine analysis produced for this patient.',
    family_reassurance_message: 'The medical team is reviewing this record directly.',
    pipeline_recommendation: src.pipeline_recommendation || 'Not provided',
    clinical_status: 'Indeterminate', risk_score: 1.0,
    low_confidence_flag: true, disagreement_flag: false, blind_class_risk: false,
    ground_truth_miss: src.correct === false, human_review_required: true,
    review_reason: 'FAIL-SAFE: clinical agent unreachable - escalated by default',
    governance_policy: 'v2.0-integrated fail-safe path',
    route: 'Clinical Review Queue', clinical_review_status: 'Pending - Fail-Safe Escalation'
  }};
});

