(() => {
  const gov = $("Normalise & Govern").item.json || {};
  const src = $("Validate & Route Input").item.json || {};
  const api = $("Call Clinical Agent API").item.json || {};

  function firstValue(...values) {
    for (const value of values) {
      if (value !== undefined && value !== null && value !== "") {
        return value;
      }
    }
    return undefined;
  }

  function toNumber(value, fallback = 0) {
    const number = Number(value);
    return Number.isFinite(number) ? number : fallback;
  }

  const classCandidates = [
    gov.predicted_class_aami,
    gov.prediction,
    src.predicted_class_aami,
    src.prediction,
    src.result,
    src.class,
    api.features?.predicted_class_aami,
    api.features?.prediction,
    api.predicted_class_aami,
    api.prediction
  ]
    .filter(value => value !== undefined && value !== null && value !== "")
    .map(value => String(value).trim().toUpperCase());

  const hasAbnormalClass = classCandidates.some(value =>
    ["S", "V", "F", "Q"].includes(value)
  );

  const abnormalBeatCount = toNumber(firstValue(
    gov.abnormal_beat_count,
    gov.abnormal_beats,
    gov.influential_abnormal_beats,
    gov.abnormal_or_influential_beats,
    src.abnormal_beat_count,
    src.abnormal_beats,
    src.influential_abnormal_beats,
    src.abnormal_influential_beats,
    src.abnormal_or_influential_beats,
    api.abnormal_beat_count,
    api.abnormal_beats,
    api.features?.abnormal_beat_count,
    api.features?.abnormal_beats,
    0
  ));

  const isAbnormalCase =
    hasAbnormalClass ||
    abnormalBeatCount > 0;

  return isAbnormalCase
    ? "Clinical ECG waveform review required - " + (gov.patient_id || "patient")
    : "ECG waveform review summary - " + (gov.patient_id || "patient");
})()
}}

parameters.text:
={{
(() => {
  const fetch = $("Fetch Patient & Doctor Emails").item.json || {};
  const gov = $("Normalise & Govern").item.json || {};
  const src = $("Validate & Route Input").item.json || {};
  const api = $("Call Clinical Agent API").item.json || {};

  function firstValue(...values) {
    for (const value of values) {
      if (value !== undefined && value !== null && value !== "") {
        return value;
      }
    }
    return undefined;
  }

  function toNumber(value, fallback = 0) {
    const number = Number(value);
    return Number.isFinite(number) ? number : fallback;
  }

  function hasValue(value) {
    return (
      value !== undefined &&
      value !== null &&
      value !== "" &&
      value !== "Not provided" &&
      value !== "Unknown"
    );
  }

  function cleanText(value) {
    return String(value || "")
      .replace(/Model predicted [^,|.]+,?\s*/gi, "")
      .replace(/Abnormal rhythm predicted\s*\([^)]*\)/gi, "Abnormal rhythm evidence was detected")
      .replace(/Prediction:\s*[^|.\n]+/gi, "")
      .replace(/AAMI class:\s*[^|.\n]+/gi, "")
      .replace(/Confidence:\s*[^|.\n]+/gi, "")
      .replace(/Risk score:\s*[^|.\n]+/gi, "")
      .replace(/Composite risk score [^|.]+/gi, "")
      .replace(/Agent status:\s*[^|.\n]+/gi, "")
      .replace(/class recall [^|.\n]+/gi, "")
      .replace(/MC-Dropout uncertainty is high/gi, "Uncertainty-related review trigger was raised")
      .replace(/\b[VNSFQ]\b/g, "")
      .replace(/\s*\|\s*/g, ". ")
      .replace(/\s+/g, " ")
      .replace(/^but\s+/i, "")
      .trim();
  }

  function cleanPointer(pointer) {
    const text = cleanText(pointer);
    const lower = text.toLowerCase();

    const banned = [
      "prediction",
      "predicted",
      "aami",
      "confidence",
      "risk score",
      "composite risk",
      "model output",
      "model predicted",
      "class recall"
    ];

    if (!text) return null;
    if (banned.some(term => lower.includes(term))) return null;

    return text;
  }

  const profile = fetch.profiles || {};
  const patientName = profile.full_name || gov.patient_id || "Not provided";

  const classCandidates = [
    gov.predicted_class_aami,
    gov.prediction,
    src.predicted_class_aami,
    src.prediction,
    src.result,
    src.class,
    api.features?.predicted_class_aami,
    api.features?.prediction,
    api.predicted_class_aami,
    api.prediction
  ]
    .filter(value => value !== undefined && value !== null && value !== "")
    .map(value => String(value).trim().toUpperCase());

  const hasAbnormalClass = classCandidates.some(value =>
    ["S", "V", "F", "Q"].includes(value)
  );

  const abnormalBeatCount = toNumber(firstValue(
    gov.abnormal_beat_count,
    gov.abnormal_beats,
    gov.influential_abnormal_beats,
    gov.abnormal_or_influential_beats,
    src.abnormal_beat_count,
    src.abnormal_beats,
    src.influential_abnormal_beats,
    src.abnormal_influential_beats,
    src.abnormal_or_influential_beats,
    api.abnormal_beat_count,
    api.abnormal_beats,
    api.features?.abnormal_beat_count,
    api.features?.abnormal_beats,
    0
  ));

  const isAbnormalCase =
    hasAbnormalClass ||
    abnormalBeatCount > 0;

  const detectedRPeaks = firstValue(
    gov.detected_r_peaks,
    gov.r_peak_count,
    src.detected_r_peaks,
    src.r_peak_count,
    src.r_peaks,
    src.num_r_peaks,
    api.detected_r_peaks,
    api.features?.detected_r_peaks,
    api.features?.r_peak_count
  );

  const signalQuality = firstValue(
    gov.signal_quality,
    src.signal_quality,
    src.signal_quality_score,
    src.quality_score,
    api.signal_quality,
    api.features?.signal_quality
  );

  const irregularityScore = firstValue(
    gov.irregularity_score,
    gov.rr_irregularity_score,
    src.irregularity_score,
    src.rr_irregularity_score,
    src.rr_variance_proxy,
    api.features?.rr_variance_proxy,
    api.rr_variance_proxy
  );

  const qrsDuration = firstValue(
    gov.qrs_duration_ms,
    src.qrs_duration_ms,
    src.mean_qrs_duration_ms,
    api.qrs_duration_ms,
    api.features?.qrs_duration_ms
  );

  const dominantRegion = firstValue(
    gov.dominant_ecg_region,
    src.dominant_ecg_region,
    api.features?.dominant_ecg_region
  );

  const problems = [];

  if (isAbnormalCase) {
    if (abnormalBeatCount > 0) {
      problems.push(`Abnormal or influential beats identified: ${abnormalBeatCount}`);
    }

    if (hasValue(irregularityScore)) {
      problems.push(`Rhythm timing / RR-interval irregularity evidence: ${irregularityScore}`);
    }

    if (hasValue(detectedRPeaks)) {
      problems.push(`Detected R-peaks used for rhythm assessment: ${detectedRPeaks}`);
    }

    if (hasValue(qrsDuration)) {
      problems.push(`QRS duration evidence: ${qrsDuration} ms`);
    }

    if (hasValue(dominantRegion)) {
      problems.push(`ECG region requiring attention: ${dominantRegion}`);
    }

    if (Array.isArray(gov.waveform_pointers)) {
      for (const pointer of gov.waveform_pointers) {
        const cleaned = cleanPointer(pointer);
        if (cleaned) {
          problems.push(cleaned);
        }
      }
    }

    if (hasValue(gov.review_reason)) {
      const cleanedReason = cleanText(gov.review_reason);
      if (
        cleanedReason &&
        !cleanedReason.toLowerCase().includes("score") &&
        !cleanedReason.toLowerCase().includes("prediction") &&
        !cleanedReason.toLowerCase().includes("predicted") &&
        !cleanedReason.toLowerCase().includes("aami") &&
        !cleanedReason.toLowerCase().includes("confidence")
      ) {
        problems.push(`Clinical review trigger: ${cleanedReason}`);
      }
    }

    if (hasValue(gov.pipeline_recommendation)) {
      problems.push(`Scope / source note: ${gov.pipeline_recommendation}`);
    }

    const uniqueProblems = [...new Set(problems)];

    const problemText = uniqueProblems.length
      ? uniqueProblems.map(problem => `- ${problem}`).join("\n")
      : "- Abnormal rhythm or waveform evidence was detected and requires clinician review.";

    return [
      "CLINICAL ECG WAVEFORM REVIEW REQUIRED",
      "",
      `Patient: ${patientName}`,
      `Patient ID: ${gov.patient_id || "Not provided"}`,
      `ECG record: ${gov.ecg_record || "Not provided"}`,
      "",
      "Problem identified:",
      problemText,
      "",
      "Recommended action:",
      "Please review the ECG waveform, R-peak timing, rhythm pattern, and available clinical context before making any clinical decision.",
      "",
      "Important note:",
      "This is an AI-assisted screening workflow. The email summarises waveform and rhythm evidence only and must not be treated as a final diagnosis."
    ].join("\n");
  }

  return [
    "ECG WAVEFORM REVIEW SUMMARY",
    "",
    `Patient: ${patientName}`,
    `Patient ID: ${gov.patient_id || "Not provided"}`,
    `ECG record: ${gov.ecg_record || "Not provided"}`,
    "",
    "Summary:",
    "No immediate abnormal waveform issue was identified by the workflow.",
    "",
    hasValue(detectedRPeaks) ? `R-peak evidence: ${detectedRPeaks} detected R-peaks were used for rhythm assessment.` : "",
    `Abnormal beat evidence: ${abnormalBeatCount} abnormal or influential beats were identified.`,
    hasValue(signalQuality) ? `Signal quality evidence: ${signalQuality}.` : "",
    "",
    "Recommended action:",
    "Routine monitoring can continue. Review the ECG trace if required by local clinical procedure.",
    "",
    "Important note:",
    "This is an AI-assisted screening workflow. The email summarises waveform and rhythm evidence only and must not be treated as a final diagnosis."
  ].filter(line => line !== "").join("\n");
})()
}}

