// Build one tamper-evident audit record per patient.
function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0; }
  return ('00000000' + h.toString(16)).slice(-8);
}
return $input.all().map(item => {
  const d = item.json;
  const record = {
    audit_version: '2.0-unified', run_id: d.run_id || 'unknown', patient_id: d.patient_id || 'unknown',
    logged_at: new Date().toISOString(), fl_checkpoint: d.fl_checkpoint || 'unknown', fl_round: d.fl_round ?? null,
    sample_index: d.sample_index ?? null, prediction: d.prediction || 'unknown',
    predicted_class_aami: d.predicted_class_aami || 'unknown', true_class_aami: d.true_class_aami || 'unknown',
    confidence: d.confidence ?? null, calibrated_confidence: d.calibrated_confidence ?? null,
    uncertainty_level: d.uncertainty_level || 'unknown', normalized_entropy: d.normalized_entropy ?? null,
    class_recall: d.class_recall ?? null, dominant_ecg_region: d.dominant_ecg_region || 'unknown',
    qrs_shap_signed: d.qrs_shap_signed ?? null, api_status: d.api_status || 'unknown',
    urgency_level: d.urgency_level || 'unknown', suggested_next_action: d.suggested_next_action || 'unknown',
    clinical_status: d.clinical_status || 'unknown', risk_score: d.risk_score ?? null,
    human_review_required: d.human_review_required ?? false, review_reason: d.review_reason || 'not recorded',
    governance_policy: d.governance_policy || 'not recorded', route: d.route || 'unknown',
    clinical_review_status: d.clinical_review_status || 'Not required', review_mode: d.review_mode || 'n/a',
    hitl_released_at: d.hitl_released_at || null, low_confidence_flag: d.low_confidence_flag ?? false,
    disagreement_flag: d.disagreement_flag ?? false, blind_class_risk: d.blind_class_risk ?? false,
    ground_truth_miss: d.ground_truth_miss ?? false,
    patient_notification_status: d.patient_notification_status || 'unavailable',
    doctor_notification_status: d.doctor_notification_status || 'unavailable',
  };
  record.integrity_checksum = fnv1a(JSON.stringify(record));
  record.audit_status = 'Completed';
  return { json: record };
});

// Aggregate all patient records into one audit log.
const records = $input.all().map(i => i.json);
const escalated = records.filter(r => r.human_review_required);
const count = (pred) => records.filter(pred).length;
return [{ json: {
  audit_log_version: '2.0-unified', run_id: records[0]?.run_id || 'unknown',
  generated_at: new Date().toISOString(), fl_checkpoint: records[0]?.fl_checkpoint || 'unknown',
  fl_round: records[0]?.fl_round ?? null,
  summary: {
    patients_processed: records.length, escalated_to_human: escalated.length,
    auto_cleared: records.length - escalated.length,
    escalation_rate: records.length ? Number((escalated.length / records.length).toFixed(3)) : 0,
    high_uncertainty: count(r => r.uncertainty_level === 'High'),
    low_confidence: count(r => r.low_confidence_flag), disagreements: count(r => r.disagreement_flag),
    blind_class_exposure: count(r => r.blind_class_risk), ground_truth_misses: count(r => r.ground_truth_miss),
    transport_errors: count(r => r.api_status === 'transport_error'),
    mean_risk_score: records.length ? Number((records.reduce((a, r) => a + (r.risk_score || 0), 0) / records.length).toFixed(4)) : 0
  },
  records
}}];

// Safely read governance data from the node that ran before email fetch.
// We try multiple source nodes in case this is a fail-safe item.
let original = {};
const sourceNodes = ['Normalise & Govern', 'Fail-Safe: Agent Unreachable'];
for (const nodeName of sourceNodes) {
  try {
    const src = $(nodeName).item?.json;
    if (src && src.patient_id) { original = src; break; }
  } catch(e) {}
}

// Supabase response: success = array, error = error object
let row = {};
try {
  const raw = $input.first().json;
  if (Array.isArray(raw)) {
    row = raw[0] || {};
  } else if (raw && !raw.error && !raw.message) {
    row = raw;
  }
  // If raw has error/message it's a Supabase error — keep row = {}
} catch(e) {
  row = {};
}

const patient_email = row.profiles?.email || null;
const doctor_email  = row.doctors?.profiles?.email || null;

return [{
  json: {
    ...original,
    patient_email:               patient_email,
    doctor_email:                doctor_email,
    patient_notification_status: patient_email ? 'pending' : 'unavailable',
    doctor_notification_status:  doctor_email  ? 'pending'  : 'unavailable',
  }
}];

