={{
(() => {
  const fetch = $("Fetch Patient & Doctor Emails").item.json || {};
  const gov = $("Normalise & Govern").item.json || {};
  const src = $("Validate & Route Input").item.json || {};
  const api = $("Call Clinical Agent API").item.json || {};

  function firstValue(...values) {
    for (const value of values) {
      if (value !== undefined && value !== null && value !== "") {
        return value;
      }
    }
    return undefined;
  }

  function toNumber(value, fallback = 0) {
    const number = Number(value);
    return Number.isFinite(number) ? number : fallback;
  }

  const profile = fetch.profiles || {};
  const fullName = profile.full_name || "there";
  const firstName = String(fullName).trim().split(/\s+/)[0] || "there";

  const classCandidates = [
    gov.predicted_class_aami,
    gov.prediction,
    src.predicted_class_aami,
    src.prediction,
    src.result,
    src.class,
    api.features?.predicted_class_aami,
    api.features?.prediction,
    api.predicted_class_aami,
    api.prediction
  ]
    .filter(value => value !== undefined && value !== null && value !== "")
    .map(value => String(value).trim().toUpperCase());

  const hasAbnormalClass = classCandidates.some(value =>
    ["S", "V", "F", "Q"].includes(value)
  );

  const abnormalBeatCount = toNumber(firstValue(
    gov.abnormal_beat_count,
    gov.abnormal_beats,
    gov.influential_abnormal_beats,
    gov.abnormal_or_influential_beats,
    src.abnormal_beat_count,
    src.abnormal_beats,
    src.influential_abnormal_beats,
    src.abnormal_influential_beats,
    src.abnormal_or_influential_beats,
    api.abnormal_beat_count,
    api.abnormal_beats,
    api.features?.abnormal_beat_count,
    api.features?.abnormal_beats,
    0
  ));

  const isAbnormalCase =
    hasAbnormalClass ||
    abnormalBeatCount > 0;

  if (isAbnormalCase) {
    return [
      `Hello ${firstName},`,
      "",
      "Your ECG test has been processed.",
      "",
      "The automated review found something that may need medical review. This does not mean that a final diagnosis has been made.",
      "",
      "A doctor will review the result and contact you shortly if follow-up is needed.",
      "",
      "Please do not make medical decisions based only on this automated message.",
      "",
      "If you feel unwell, have chest pain, shortness of breath, fainting, dizziness, or worsening symptoms, please seek urgent medical help immediately.",
      "",
      "Thank you."
    ].join("\n");
  }

  return [
    `Hello ${firstName},`,
    "",
    "Your ECG test has been processed.",
    "",
    "The automated review did not identify anything that needs urgent medical attention.",
    "",
    "A healthcare professional may still review the result as part of normal care.",
    "",
    "Please continue to follow any advice already given by your healthcare team.",
    "",
    "If you feel unwell, have chest pain, shortness of breath, fainting, dizziness, or severe symptoms, please seek medical help.",
    "",
    "Thank you."
  ].join("\n");
})()
}}

