// Record whether patient email actually sent or failed
const d = $input.first().json;
const sent = !d.error && !d.message;  // if error object arrived, it failed
return [{
  json: {
    ...d,
    patient_notification_status: sent ? 'sent' : 'failed',
  }
}];

// Record whether the detailed doctor email was sent to the assigned doctor or fallback route.
const d = $input.first().json;
const failed = !!(d.error || d.message);
const hasAssignedDoctor = !!d.doctor_email;
const hasFallbackDoctor = !!$env.FALLBACK_DOCTOR_EMAIL;

let status = 'unavailable';
if (failed) {
  status = 'failed';
} else if (hasAssignedDoctor) {
  status = 'sent_to_assigned_doctor';
} else if (hasFallbackDoctor) {
  status = 'fallback_sent';
}

return [{
  json: {
    ...d,
    doctor_notification_status: status,
  }
}];
